// loadTaskAuthorshipMap fetches created_by + updated_by ids and joined user
// display names for the given task IDs.
func (s *Server) loadTaskAuthorshipMap(ctx context.Context, taskIDs []int64) map[int64]struct {
	CreatedByID   *int64
	CreatedByName *string
	UpdatedByID   *int64
	UpdatedByName *string
} {
	type row struct {
		CreatedByID   *int64
		CreatedByName *string
		UpdatedByID   *int64
		UpdatedByName *string
	}
	out := make(map[int64]row)
	if len(taskIDs) == 0 {
		result := make(map[int64]struct {
			CreatedByID   *int64
			CreatedByName *string
			UpdatedByID   *int64
			UpdatedByName *string
		})
		return result
	}
	args := make([]interface{}, len(taskIDs))
	placeholders := make([]string, len(taskIDs))
	for i, id := range taskIDs {
		args[i] = id
		placeholders[i] = "$" + strconv.Itoa(i+1)
	}
	query := `
		SELECT t.id, t.created_by, t.updated_by,
		       COALESCE(uc.first_name || ' ' || uc.last_name, uc.name, uc.email) AS created_by_name,
		       COALESCE(uu.first_name || ' ' || uu.last_name, uu.name, uu.email) AS updated_by_name
		FROM tasks t
		LEFT JOIN users uc ON uc.id = t.created_by
		LEFT JOIN users uu ON uu.id = t.updated_by
		WHERE t.id IN (` + strings.Join(placeholders, ",") + `)
	`
	rows, err := s.db.QueryContext(ctx, query, args...)
	if err != nil {
		s.logger.Warn("Failed to load task authorship", zap.Error(err))
		result := make(map[int64]struct {
			CreatedByID   *int64
			CreatedByName *string
			UpdatedByID   *int64
			UpdatedByName *string
		})
		return result
	}
	defer rows.Close()
	for rows.Next() {
		var id int64
		var createdBy, updatedBy sql.NullInt64
		var createdName, updatedName sql.NullString
		if err := rows.Scan(&id, &createdBy, &updatedBy, &createdName, &updatedName); err != nil {
			continue
		}
		r := row{}
		if createdBy.Valid {
			v := createdBy.Int64
			r.CreatedByID = &v
		}
		if createdName.Valid && createdName.String != "" {
			v := createdName.String
			r.CreatedByName = &v
		}
		if updatedBy.Valid {
			v := updatedBy.Int64
			r.UpdatedByID = &v
		}
		if updatedName.Valid && updatedName.String != "" {
			v := updatedName.String
			r.UpdatedByName = &v
		}
		out[id] = r
	}
	result := make(map[int64]struct {
		CreatedByID   *int64
		CreatedByName *string
		UpdatedByID   *int64
		UpdatedByName *string
	}, len(out))
	for id, r := range out {
		result[id] = struct {
			CreatedByID   *int64
			CreatedByName *string
			UpdatedByID   *int64
			UpdatedByName *string
		}{r.CreatedByID, r.CreatedByName, r.UpdatedByID, r.UpdatedByName}
	}
	return result
}

